import React, { useState, useEffect, useContext } from 'react';
import EventForm from './EventForm';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

const Dashboard = () => {
  const [events, setEvents] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const { user, logout } = useContext(AuthContext) || {};
  const navigate = useNavigate();

  const fetchEvents = async () => {
    // Only fetch if user and user._id are actually loaded
    if (!user || !user._id) return;

    try {
      const res = await axios.get(`http://localhost:5000/api/events?userId=${user._id}`);
      setEvents(res.data);
    } catch (err) {
      console.error("Fetch error", err);
    }
  };

  useEffect(() => {
    fetchEvents();
  }, [user]);

  const styles = {
    container: { minHeight: '100vh', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', padding: '40px 20px' },
    wrapper: { maxWidth: '1100px', margin: '0 auto' },
    card: { backgroundColor: 'white', padding: '25px', borderRadius: '15px', marginBottom: '30px', boxShadow: '0 10px 30px rgba(0,0,0,0.2)' },
    grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' },
    eventItem: { backgroundColor: 'white', padding: '20px', borderRadius: '12px', borderLeft: '6px solid #667eea' },
    empty: { textAlign: 'center', color: 'white', padding: '60px', backgroundColor: 'rgba(255,255,255,0.15)', borderRadius: '15px', marginTop: '20px' }
  };

  return (
    <div style={styles.container}>
      <div style={styles.wrapper}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', color: 'white', marginBottom: '30px' }}>
          <h1>📊 Dashboard</h1>
          <div>
            <span style={{ marginRight: '20px', fontWeight: 'bold' }}>Hello, {user?.name || 'User'}</span>
            <button onClick={() => { logout(); navigate('/'); }} style={{ padding: '8px 15px', borderRadius: '6px', border: 'none', cursor: 'pointer', backgroundColor: '#f44336', color: 'white' }}>Logout</button>
          </div>
        </div>

        <div style={styles.card}>
          <button
            onClick={() => setShowForm(!showForm)}
            style={{ marginBottom: showForm ? '20px' : '0', padding: '10px 20px', backgroundColor: '#667eea', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}
          >
            {showForm ? "✕ Close Form" : "+ Create New Event"}
          </button>

          {showForm && (
            <EventForm
              currentUserId={user?._id}
              onEventCreated={() => { fetchEvents(); setShowForm(false); }}
            />
          )}
        </div>

        <h2 style={{ color: 'white', marginBottom: '20px' }}>Your Events</h2>

        {events.length === 0 ? (
          <div style={styles.empty}>
            <div style={{ fontSize: '60px', marginBottom: '10px' }}>📅</div>
            <h2>No events at the moment</h2>
            <p>Create an event or wait for someone to invite you!</p>
          </div>
        ) : (
          <div style={styles.grid}>
            {events.map(e => (
              <div key={e._id} style={styles.eventItem}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                  <span style={{ fontSize: '11px', padding: '3px 8px', borderRadius: '4px', backgroundColor: e.creator?._id === user?._id ? '#eef2ff' : '#fff7ed', color: e.creator?._id === user?._id ? '#667eea' : '#ea580c', fontWeight: 'bold', textTransform: 'uppercase' }}>
                    {e.creator?._id === user?._id ? "Organizer" : "Invited"}
                  </span>
                  <span style={{ fontSize: '12px', color: '#888' }}>{new Date(e.date).toLocaleDateString()}</span>
                </div>
                <h3 style={{ margin: '0 0 10px 0', color: '#333' }}>{e.name}</h3>
                <p style={{ color: '#666', fontSize: '14px', margin: '4px 0' }}>📍 {e.location || 'No location'}</p>
                <p style={{ color: '#999', fontSize: '12px', margin: '4px 0' }}>👤 Organized by: {e.creator?.name || 'Unknown'}</p>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
